class ConnectGame:
    """A game of Hex / Polygon (Connect).

    The board is a parallelogram of hexagonal cells given as text, where
    each row is indented one extra character so the cells form a
    slanted grid.  Player ``X`` tries to connect the left side to the
    right side; player ``O`` tries to connect the top side to the bottom
    side.  Two cells are adjacent if they share a hex edge, which in the
    row/column coordinates of the grid means: same row next column, or
    the row above/below at the same or next column (the rows are shifted
    by half a cell).
    """

    def __init__(self, board):
        self.grid = [line.split() for line in board.splitlines() if line.strip()]
        self.rows = len(self.grid)

    def get_winner(self):
        for player in ("X", "O"):
            if self._connects(player):
                return player
        return ""

    def _connects(self, player):
        if player == "X":
            start = {(r, 0) for r, row in enumerate(self.grid) if row and row[0] == player}

            def on_goal(r, c):
                return c == len(self.grid[r]) - 1
        else:
            if not self.grid:
                return False
            start = {(0, c) for c, cell in enumerate(self.grid[0]) if cell == player}

            def on_goal(r, c):
                return r == self.rows - 1

        if not start:
            return False

        seen = set(start)
        stack = list(start)
        while stack:
            r, c = stack.pop()
            if on_goal(r, c):
                return True
            for dr, dc in ((0, -1), (0, 1), (-1, 0), (-1, 1), (1, -1), (1, 0)):
                nr, nc = r + dr, c + dc
                if (
                    0 <= nr < self.rows
                    and 0 <= nc < len(self.grid[nr])
                    and self.grid[nr][nc] == player
                    and (nr, nc) not in seen
                ):
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        return False

